using LocadoraVeiculos.Api.Data; using LocadoraVeiculos.Api.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace LocadoraVeiculos.Api.Controllers;
[ApiController,Route("api/[controller]")] public class AlugueisController:ControllerBase {private readonly LocadoraContext _db; public AlugueisController(LocadoraContext db)=>_db=db;
 [HttpGet] public async Task<IActionResult> Get()=>Ok(await _db.Alugueis.AsNoTracking().Include(a=>a.Cliente).Include(a=>a.Veiculo).ToListAsync());
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await _db.Alugueis.Include(a=>a.Cliente).Include(a=>a.Veiculo).FirstOrDefaultAsync(a=>a.Id==id);return x is null?NotFound():Ok(x);}
 [HttpPost] public async Task<IActionResult> Post(Aluguel x){if(x.DataFimPrevista<x.DataInicio)return BadRequest(new{erro="Data final deve ser posterior à inicial."});var v=await _db.Veiculos.FindAsync(x.VeiculoId);if(v is null||!v.Disponivel)return BadRequest(new{erro="Veículo inexistente ou indisponível."});if(!await _db.Clientes.AnyAsync(c=>c.Id==x.ClienteId))return BadRequest(new{erro="Cliente inexistente."});x.QuilometragemInicial=v.Quilometragem;v.Disponivel=false;_db.Alugueis.Add(x);await _db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
 [HttpPut("{id:int}")] public async Task<IActionResult> Put(int id,Aluguel x){if(id!=x.Id)return BadRequest();if(!await _db.Alugueis.AnyAsync(a=>a.Id==id))return NotFound();_db.Entry(x).State=EntityState.Modified;await _db.SaveChangesAsync();return NoContent();}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var x=await _db.Alugueis.FindAsync(id);if(x is null)return NotFound();_db.Remove(x);await _db.SaveChangesAsync();return NoContent();}
 [HttpPost("{id:int}/devolver")] public async Task<IActionResult> Devolver(int id,int quilometragemFinal){var a=await _db.Alugueis.Include(x=>x.Veiculo).FirstOrDefaultAsync(x=>x.Id==id);if(a is null)return NotFound();if(a.DataDevolucao!=null)return BadRequest(new{erro="Aluguel já devolvido."});if(quilometragemFinal<a.QuilometragemInicial)return BadRequest(new{erro="Quilometragem final inválida."});a.DataDevolucao=DateTime.Now;a.QuilometragemFinal=quilometragemFinal;var dias=Math.Max(1,(int)Math.Ceiling((a.DataDevolucao.Value-a.DataInicio).TotalDays));a.ValorTotal=dias*a.ValorDiaria;if(a.Veiculo!=null){a.Veiculo.Quilometragem=quilometragemFinal;a.Veiculo.Disponivel=true;}await _db.SaveChangesAsync();return Ok(a);}
}
